(() => {
 'use strict';
 // Reviewed against local MSC QRG 2025.1: PSHELL PDF2676–2677, PSOLID PDF2699,
 // SPC1 PDF2884 and CONM2 PDF1462. Original questions; no manual examples reproduced.
 const base=window.AnalysisQuiz.data;
 const check=(label,expect,diag=[])=>({label,expect,diag:[[1,'力・モーメントのつり合い、または選んだ条件の理論値と一致します。'],...diag]});
 const shell={intro:'選択中：シェルの片持ち板。長さ360 mm、幅36 mm、板厚6 mm、CQUAD4とPSHELLを使います。根元はGRID 1〜5、先端はGRID 61〜65です。梁の断面入力と、板厚・辺への荷重分配を区別する3問です。',links:[['bulk.html#SPC1','SPC1'],['bulk.html#FORCE','FORCE'],['bulk.html#PSHELL','PSHELL'],['elements.html#shell','シェル要素']],questions:[
  {title:'固定するのは1点か、辺全体か（SPC1）',line:['SPC1','10','123456','？'],ask:'このモデルの根元の辺を固定する指定は？',options:[['1','辺の一端だけの固定です。残りの根元が動けるので、辺全体を固定した片持ち板とは異なります。'],['1 2 3 4 5を別々のG欄へ','根元の5点すべてを同じSPCセットに含めます。各節点番号は別の8文字欄に置きます。'],['61 62 63 64 65を別々のG欄へ','これは先端の荷重側です。固定する辺が逆になります。'],['成分を123にしてGRID 1だけ','根元の回転も残り、辺全体の固定にはなりません。シェルの曲げ回転をソリッドの自由度と混同しないようにします。']],answer:1,verify:{title:'根元の反力を合計する',steps:['根元5点のSPCFORCESのT3を足します。1点の値だけを18 Nと比較しません。','外力の合計は−18 Nなので、反力の合計は+18 N。','根元のR2と、各点の位置×並進反力も含めると、Y軸まわりの反力モーメントは−6,480 N·mmです。'],note:'合計が合っても拘束位置の正しさは保証しません。根元の全節点の変位・回転も確認します。',check:check('GRID 1〜5のT3合計（N）',18,[[-1,'反力の符号と荷重の向きを確認します。']])}},
  {title:'辺へ18 Nを配る（FORCE）',line:['FORCE','40','63','0','？','0.','0.','-1.'],ask:'幅方向に等間隔の5点。端点を半分の負担幅とすると、中央GRID 63のFは？',options:[['18.','5点のそれぞれに18 Nを置くと総荷重が変わります。'],['3.6','均等5分配は総和は合いますが、このモデルの端点半分の分配とは異なります。'],['4.5','重み1:2:2:2:1の合計は8。中央は18×2/8=4.5 N、端は2.25 Nです。'],['-4.5','N3も−1なので、力は+Z向きになります。']],answer:2,verify:{title:'合力を確かめる',steps:['2.25 + 4.5 + 4.5 + 4.5 + 2.25 = 18 N。','全点のN3は−1なので、OLOAD RESULTANTのT3は−18 N。','根元まわりの外力モーメントは+18×360=+6,480 N·mm。'],note:'分布の正しさと合力の正しさは別です。局所変形を見る場合は分配の違いも評価します。',check:check('OLOAD RESULTANTのT3（N）',-18,[[-1,'二重に負号を入れていないか確認します。'],[5,'5点の各点へ18 Nを与えていないか確認します。']])}},
  {title:'板の曲げ剛性を有効にする（PSHELL）',line:['PSHELL','20','70','6.','？','','70'],ask:'材料70を使って膜と曲げを扱います。MID2は？',options:[['空欄','この指定では曲げ材料を与えません。板厚を入れただけでは、意図した板曲げモデルになりません。'],['648.','648 mm⁴は梁断面のIです。MID2は断面二次モーメントではなく材料IDです。'],['6.','6 mmはTの値。材料IDとは役割が違います。'],['70','MID2に材料ID 70を指定します。板厚6 mmと材料のE・νから板の曲げ剛性を構成します。']],answer:3,verify:{title:'板厚・質量・曲げ剛性を別々に確かめる',steps:['体積V=360×36×6=77,760 mm³。ρ=2.70×10⁻⁹ tonne/mm³なので総質量m=0.000209952 tonne。','掲載の静解析DATに質量表の出力を追加した場合は、GPWGの総質量から板厚と密度の積を点検できます。ただし質量が合ってもMID2の指定を保証しません。','曲げはMID2と板厚を確認し、荷重方向の変位と上下両面の応力を調べます。板厚2倍なら質量2倍、曲げ剛性8倍です。'],note:'梁近似の公称曲げ応力30 MPaを、シェルの固定辺の局所最大値への合格基準にはしません。固定辺から離した断面・出力位置・メッシュ収束をそろえて評価します。',check:check('GPWGの総質量（tonne）',.000209952,[[1000,'N・mm・sの密度換算を確認します。']])}}
 ]};
 const solid={intro:'選択中：ソリッドの片持ち体。長さ360 mm、36×6 mmの体積をCHEXAで分割し、PSOLIDからMAT1を参照します。根元はGRID 1〜15、荷重面はGRID 361〜375。並進自由度・体積形状・端面への荷重分配を確かめる3問です。',links:[['bulk.html#SPC1','SPC1'],['bulk.html#FORCE','FORCE'],['bulk.html#PSOLID','PSOLID'],['elements.html#solid','ソリッド要素']],questions:[
  {title:'固定端の面を止める（SPC1）',line:['SPC1','10','？','1','2','3','4','5','6'],ask:'根元15点すべてに同じ指定を続けます。ソリッドの物理的な固定に必要な成分は？',options:[['123','各節点の並進3成分を止めます。面全体の並進を止めることで断面も回らなくなります。'],['456','通常のソリッドの剛性は回転自由度を使いません。回転だけを拘束しても体積は動きます。'],['3','Z方向だけを止め、X・Y方向の剛体移動が残ります。'],['GRID 1だけ123','点を止めただけでは、その点を中心に物体が回れます。根元面全体の固定とは異なります。']],answer:0,verify:{title:'面全体の反力で確認する',steps:['根元15点のT3の合計は+18 Nです。','ソリッドは節点のR2だけで曲げ反力を読みません。各点の位置rと並進反力RからΣ(r×R)yを計算します。','この例は基本座標で、Σ(zRx−xRz)=−6,480 N·mm。根元x=0なので主にzRxの偶力で受け持ちます。'],note:'反力を足す前に座標系と原点をそろえます。回転自由度を止めることと、複数点の並進を止めて断面回転を止めることは別です。',check:check('GRID 1〜15のT3合計（N）',18)}},
  {title:'厚さをどこで決めるか（PSOLID）',line:['PSOLID','20','？'],ask:'PSOLIDのMIDと、36×6 mmの断面形状はどこで指定しますか？',options:[['MID=6、PSOLIDのT=36','PSOLIDにはシェルのTに相当する板厚欄はありません。'],['MID=70、GRID座標とCHEXAの接続で体積を決める','材料はMAT1の70。寸法は節点座標、体積の区切りは要素の接続です。'],['MID=648、PBEAMで断面を与える','648は梁のI。ソリッドの材料IDや断面指定には使いません。'],['MAT1のRHOで厚さを変える','密度を変えても体積形状や静的な曲げ剛性は変わりません。']],answer:1,verify:{title:'体積と材料密度を照合する',steps:['V=360×36×6=77,760 mm³。','ρ=2.70×10⁻⁹ tonne/mm³なので、m=0.000209952 tonne。','PARAM,GRDPNT,0のGPWGで総質量を確認します。寸法や密度の単位を間違えると、この積が変わります。'],note:'総質量一致だけで曲げ精度は判定できません。板厚方向と長手方向のメッシュで、たわみと断面応力の収束も調べます。',check:check('GPWGの総質量（tonne）',.000209952,[[1000,'N・mm・sでkg/mm³の密度を使っていないか確認します。']])}},
  {title:'端面15点の負担面積で配る（FORCE）',line:['FORCE','40','368','0','？','0.','0.','-1.'],ask:'端面は幅方向5点×厚さ方向3点。角は0.5625 N、辺の内部は1.125 Nです。中央GRID 368は？',options:[['18.','1点へ全荷重を集中すると、局所的な荷重条件が別になります。'],['1.2','15等分は総和は合いますが、均一な面荷重に対応するこのモデルの面積重みとは異なります。'],['0.5625','角の負担面積です。内部点の負担面積は角の4倍あります。'],['2.25','幅の重み1:2:2:2:1と厚さの重み1:2:1の積。総和32、中央は18×4/32=2.25 Nです。']],answer:3,verify:{title:'15点の合力と作用位置を確かめる',steps:['角4点×0.5625 + 辺の内部8点×1.125 + 面の内部3点×2.25 = 18 N。','全点がx=360 mmにあり、方向は−Z。OLOAD RESULTANTのT3=−18 N。','幅方向に対称なので、意図しないねじりの合力モーメントは0です。'],note:'均一な面荷重を節点に配る考え方です。実際の接触面圧分布を解析した結果ではありません。',check:check('OLOAD RESULTANTのT3（N）',-18,[[-1,'FORCEの大きさと方向の負号を確認します。'],[15,'15点それぞれに18 Nを入れていないか確認します。']])}}
 ]};
 window.AnalysisModelQuizzes={static:{beam:base.static,shell,solid},modes:window.AnalysisModeQuiz.models};
 // A short, model-specific route sits above expandable shared guidance.
 window.AnalysisModelGuides={
  beam:{title:'梁：1本の線と断面特性で曲げを表す',items:['CBEAMのGA→GBと向きベクトルを確認し、PBEAMのI1=648、I2=23328が荷重方向と対応するか調べます。','根元GRID 1の6成分を止め、GRID 13へ−Zに18 N。反力T3とR2、先端T3、根元のC〜Fの応力を読む順です。','梁の反力モーメントは節点の回転自由度に対応します。シェルやソリッドの値をそのまま同じ欄で探さないでください。']},
  shell:{title:'シェル：中央面・板厚・表裏を対応させる',items:['CQUAD4の節点順で法線を確認し、PSHELLのT=6とMID1・MID2・MID3=70を照合します。','固定するのはGRID 1〜5の辺全体。先端61〜65へ2.25、4.5、4.5、4.5、2.25 Nを配ります。','反力は固定辺で合計。応力はZ1・Z2の両面と表示座標を確認します。固定辺の局所ピークと梁近似の30 MPaを直接同一視しません。']},
  solid:{title:'ソリッド：体積の形状と面への荷重・拘束を確認する',items:['CHEXAとGRIDで厚さ6 mmを含む体積を表し、PSOLIDから材料70を参照します。PSOLIDへ板厚や断面Iを入力する方式ではありません。','根元GRID 1〜15の並進123を止めます。先端361〜375へ負担面積に応じて合計18 Nを配ります。','反力モーメントは複数節点の並進反力の偶力として集計します。板厚方向の分割と曲げ応力・たわみの収束を確認します。']},
  baseline:{title:'基準の片持ち梁：拘束と分布質量から固有値を確認する',items:['GRID 1だけを123456で固定。CONM2はありません。MAT1の密度による総質量は0.209952 kgです。','METHOD=30からEIGRL 30、ND=12を参照。LOADは使わず、モード形とREAL EIGENVALUESを読みます。','最初の弱軸曲げの理論値は約38.08 Hz。表示倍率やMASS規格化で実際の振幅を予測したと考えないでください。']},
  'tip-mass':{title:'先端質量付き：質量を加えた位置とモードの変化を見る',items:['基準と同じ片持ち拘束に、GRID 13のCONM2 201で0.08 kgを追加。総質量は0.289952 kgです。','MAT1の密度を全体で増やすのとは異なります。動きの大きい先端に質量を足すため、各モードへの影響が一様ではありません。','GPWGの総質量、追加位置の変位、振動数の順に確認します。入力タブのRayleigh値は近似の目安で、MSC実行結果ではありません。']},
  'both-fixed':{title:'両端固定：質量を変えずに境界条件だけを変える',items:['SPC1 10でGRID 1と13の123456を固定。CONM2はなく、総質量は基準と同じ0.209952 kgです。','両端の変位・傾きは0になり、第1曲げは中央が大きく動きます。片持ちの先端変位で振動数を照合しません。','β1=4.730041を使った弱軸曲げの理論値は約242.31 Hz。拘束の変更とE・密度の変更を分けて比較します。']}
 };
 const traps={
  beam:[['反力が18 Nなら正しい？','反力はつり合いから決まるので、EやIが間違っても合うことがあります。先端変位と断面応力も確認し、I1/I2の入替え・単位違いを切り分けます。'],['根元を123だけ固定した','梁には回転自由度があり、根元まわりの剛体回転が残ります。AUTOSPCで実行が終わったことを、意図した固定端の証拠にしないでください。']],
  shell:[['先端5点へ各18 Nを入れた','合計90 Nとなります。全体の荷重18 Nと各節点への分担を分け、OLOADの合力→SPCFORCESの合計→変形の順に確認します。'],['Z1の応力同士を比較した','節点順が逆のモデルでは、Z1が指す物理的な面も逆です。法線と実物の上下面を対応させてから、同じ位置・同じ方向の応力を比較します。'],['固定辺の最大応力が30 MPaではない','30 MPaは梁近似の公称値です。固定辺の局所効果や応力の出力位置を区別し、固定辺から離した断面の分布・合力とメッシュ収束で確認します。']],
  solid:[['123を1点だけ止めれば固定になる？','点を中心に物体が回れます。面全体の並進を拘束することと、1点の並進を拘束することは同じではありません。'],['ソリッドなのにR2が出ない','通常のソリッドは節点の並進自由度で力を伝えます。根元面のΣ(zRx−xRz)を計算し、節点回転の反力だけを探さないでください。'],['要素数だけ増やせば曲げ精度が上がる？','分割方向も重要です。長手だけでなく厚さ方向の分割を変え、先端たわみと断面応力の両方が落ち着くかを調べます。']],
  baseline:[['モード図が6 mm動くから実振幅も6 mm？','SOL 103は外力に対する応答振幅を求めません。規格化と表示倍率を変えても振動数が変わらないことを、入力タブの操作図で確かめます。'],['静解析が合えば密度も正しい？','重力などを含まない通常の静荷重では、密度を間違えてもたわみが合います。GPWGで質量を独立に確認します。']],
  'tip-mass':[['総質量比から全モードを同じ倍率で下げた','同じ80 gでも、その曲げ方で大きく動く点に付けるほど影響が強く、動かない点では影響が小さくなります。モードごとに取り付け位置の動きを確かめます。'],['荷重18 Nを追加質量に代用した','静荷重は質量ではありません。CONM2のMに重量やkgの数値をそのまま入れず、N・mm・sならtonneへ換算します。']],
  'both-fixed':[['同じ質量だから振動数も同じ？','端を固定すると許される変形が変わり、対応する曲げの振動数が上がります。材料を変更せず、拘束だけを変えた比較です。'],['先端が動かないのでモードが出ていない？','両端固定の先端GRID 13は拘束点です。中央と両端のモード形を確認し、振動数はCYCLES列から読みます。']]
 };
 for(const [id,pitfalls] of Object.entries(traps))window.AnalysisModelGuides[id].pitfalls=pitfalls;
 const verify={
  beam:['SPC=10とLOAD=40を確認。SPCFORCESのGRID 1でT3=+18 N、R2=−6,480 N·mmを照合します。','GRID 13のT3は細長梁の理論で約−6.17 mm。向きベクトル・I1/I2・単位を確認します。','要素101の根元でC〜Fの位置と応力を確認。公称曲げ応力の大きさは30 MPaです。'],
  shell:['根元GRID 1〜5の拘束と、先端61〜65の荷重合計−18 Nを確認します。','SPCFORCESのT3は根元5点で合計+18 N。変位は先端中央GRID 63と幅方向の分布を読みます。','同じ断面の長手応力を上下面で比較。固定辺からの距離・出力位置・平均化をそろえ、板厚とメッシュの影響を分けます。'],
  solid:['固定面GRID 1〜15の123、端面361〜375の荷重合計−18 Nを確認します。','根元面のΣRz=+18 N、Σ(zRx−xRz)=−6,480 N·mm。各点のCDから同じ座標系へそろえます。','先端中央GRID 368のT3と、同じ断面の厚さ方向の長手応力を確認。厚さ方向の分割を変えたときの収束も見ます。'],
  baseline:['GPWGの総質量0.000209952 tonneを照合します。','GRID 1の拘束を確認。第1弱軸曲げの形とCYCLESを対応させ、約38.08 Hzの細長梁理論と比べます。','EIGRL 30で要求した12個の根、意図しないゼロの根、MASS規格化の一般化質量を確認します。'],
  'tip-mass':['CONM2 201がGRID 13にあり、M=0.00008 tonneであることを確認します。','GPWGの総質量は0.000289952 tonne。基準モデルとの差は0.00008 tonneです。','同じ方向の曲げモードを対応させて基準より低くなる傾向を調べます。基準の38.08 Hzや総質量比だけを正解値として使いません。','入力タブのRayleigh値は近似の目安です。MSC実行値とモード形はユーザーの実行結果で確認します。'],
  'both-fixed':['SPC1 10にGRID 1と13の123456が含まれることを確認します。','GPWGの総質量は基準と同じ0.000209952 tonne。両端のモード変位・傾きが0であることを確認します。','中央側が動く第1弱軸曲げを選び、CYCLESを約242.31 Hzの細長梁理論と比較します。','METHOD=30、EIGRLのND=12を確認。モード順だけで片持ちと対応付けず、曲げ方向と形を見ます。']
 };
 for(const [id,steps] of Object.entries(verify))window.AnalysisModelGuides[id].verify=steps;
})();
